    private static SoftwareProduct ReadProduct(SqliteDataReader r) => new(Guid.Parse(r.GetString(0)),r.GetString(1),Text(r,2),r.GetString(3),DateTimeOffset.Parse(r.GetString(4)),DateTimeOffset.Parse(r.GetString(5)),Text(r,6),Text(r,7),(UpdateStatus)r.GetInt32(8),Text(r,9),Text(r,10),Text(r,11),r.IsDBNull(12)?null:DateTimeOffset.Parse(r.GetString(12)),Text(r,13));
